-- Cupo: ligas para RPs (con ranking y panel por RP) y recuperación de entradas con NIP. Ficha de Pro y del paquete al día.
UPDATE products SET
  descripcion_corta = 'Correos automáticos (entrada, recordatorios y avisos), cobro de cover sin comisión, ligas para RPs con ranking, aprobación de registros y hasta 1,000 personas.',
  contenido = json_set(contenido,
    '$.titular', 'Correos, cover y RPs para llenar tu evento',
    '$.subtitulo', 'Arma tu evento gratis en os.vorka.mx/cupo y activa Pro al publicarlo: entrada por correo, recordatorios automáticos, avisos, cover pagado directo a ti, ligas para tus RPs y check-in con tu equipo.',
    '$.incluye', json('[{"titulo":"Correos automáticos","texto":"A cada persona le llega su entrada con QR, un recordatorio un día antes y otro dos horas antes. En el plan gratis no se manda ningún correo."},{"titulo":"Ligas para tus RPs","texto":"Una liga y un QR por RP, ranking de registros, pagos y llegadas, y un panel en su celular para ver a su gente."},{"titulo":"Cobro de cover","texto":"Tu CLABE con botón de copiar, tu liga de pago o pago en la puerta. El dinero llega directo a ti, sin comisión."},{"titulo":"10 avisos por correo","texto":"Cambios de horario, qué traer o cómo llegar, directo a su correo."},{"titulo":"Hasta 1,000 personas","texto":"Aprobar registros, preguntas personalizadas y lista de espera automática."},{"titulo":"Check-in con tu equipo","texto":"Una liga para que escaneen desde su celular, sin cuenta, y lista en Excel con el RP de cada persona."}]'),
    '$.para_quien', json('["Antros, bares y fiestas con cover y RPs","Halloween, posadas y eventos de temporada","Networking, talleres y eventos de negocio"]'),
    '$.faq', json('[{"p":"¿Qué incluye el plan gratis?","r":"Página del evento, registro y entrada con QR, lista de espera y check-in, hasta 100 personas. No manda correos: cada persona recupera su entrada en la página del evento con su correo y un NIP. Para correos, cover y RPs necesitas Pro."},{"p":"¿Puedo armar mi evento antes de pagar?","r":"Sí. En <a href=\"https://os.vorka.mx/cupo/\">os.vorka.mx/cupo</a> lo armas y ves cómo queda sin cuenta y sin pagar. Activas Pro solo cuando lo vas a publicar."},{"p":"¿Cómo funcionan las ligas de RP?","r":"En tu evento entras a “RPs”, escribes el nombre de cada uno y le mandas por WhatsApp su liga y su panel. Tú ves el ranking; cada RP ve solo a su gente (nombre y si llegó), sin correos ni teléfonos."},{"p":"¿Cupo cobra comisión por mi cover?","r":"No. Las personas te pagan directo a ti y tú confirmas cada pago. Solo pagas Cupo Pro una vez por evento."},{"p":"¿Cupo o Brindi?","r":"Cupo es para eventos rápidos o informales: fiestas, antros, Halloween, networking y talleres. Para una boda, XV años o bautizo te conviene <a href=\"/tienda/brindi/\">Brindi</a>."},{"p":"¿Cómo lo uso después de pagar?","r":"Te llega un correo con el botón “Entrar a Cupo”. Al publicar tu evento eliges usar tu evento Pro."}]')),
  updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 'prod_cupo_pro';
UPDATE products SET
  descripcion_corta = 'Cinco eventos con todo Cupo Pro (correos, cover, RPs y más) para usar en 12 meses. Sale en $109.80 por evento.',
  contenido = json_set(contenido,
    '$.subtitulo', 'Todo lo de Cupo Pro en cinco eventos: sale en $109.80 por evento (ahorras $146 contra comprarlos sueltos). Los aplicas al publicar cada evento durante 12 meses.',
    '$.incluye', json('[{"titulo":"5 eventos Pro","texto":"Correos y recordatorios, cover, ligas para RPs, aprobación, preguntas, avisos, check-in con equipo y Excel en cada uno."},{"titulo":"Ahorras $146","texto":"$549 por cinco eventos contra $695 sueltos."},{"titulo":"Sin comisiones por boleto","texto":"El dinero del cover llega directo a ti."},{"titulo":"12 meses para usarlos","texto":"Ideal para eventos mensuales, fines de semana o temporadas."}]'),
    '$.para_quien', json('["Antros, bares y cafés con eventos frecuentes","Organizadores con equipo de RPs","Comunidades de networking y emprendimiento"]')),
  updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 'prod_cupo_paquete5';
